public class RecoveryVerification : MonoBehaviour {
 readonly List<string> lines=new List<string>();int failed;string folder;Player p;Item[] prefabs;volatile string state;volatile bool readDone;
 void Check(bool pass,string text){lines.Add((pass?"PASS ":"FAIL ")+text);if(!pass)failed++;File.WriteAllLines(Path.Combine(folder,"verification-progress.txt"),lines);}
 static object Field(object obj,string name)=>obj.GetType().GetField(name,BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic)?.GetValue(obj);
 IEnumerator ReadState(){readDone=false;ThreadPool.QueueUserWorkItem(_=>{try{using(var r=new StreamReader(WebRequest.Create("http://127.0.0.1:"+RecoveryGiftPanel.Port+"/api/state").GetResponse().GetResponseStream()))state=r.ReadToEnd();}catch(Exception e){state="{\"readError\":\""+e.GetType().Name+"\"}";}readDone=true;});float until=Time.realtimeSinceStartup+6;while(!readDone&&Time.realtimeSinceStartup<until)yield return null;}
 IEnumerator Event(string id,string body){RecoveryGiftPanel.Instance.Trigger(id,body);float until=Time.realtimeSinceStartup+7;while(RecoveryGiftPanel.Instance.IsSending&&Time.realtimeSinceStartup<until)yield return null;yield return new WaitForSecondsRealtime(.3f);yield return ReadState();File.AppendAllText(Path.Combine(folder,"gift-states.jsonl"),id+" "+state+"\n");}
 Item Give(Item prefab){if(!prefab)return null;if(p.Holding.HeldItem)p.Holding.HeldItem.Drop(true);var item=ItemManager.Instance.SpawnNewItem(prefab,p.CamObject.position+p.CamObject.forward*1.5f,Quaternion.identity);item.PickUp(p,true,true);return item;}
 IEnumerator Capture(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return null;}
 public IEnumerator Run(){folder=RecoveryGiftPanel.EvidencePath;p=Player.LocalPlayer;lines.Clear();Check(p&&Server.Instance&&Island.CurIsland,"Original host, player and island initialized");if(!p)yield break;Check(RecoveryIsolation.PersistentDataPath.Contains("OriginalRecovery"),"Workspace save isolation");prefabs=Resources.LoadAll<Item>("Items");File.WriteAllLines(Path.Combine(folder,"item-catalog.txt"),prefabs.Select(x=>x.name+" | rod="+(x is FishingRod)+" | weapon="+(x is Weapon)+" | creature="+(x is Creature)));Check(prefabs.Length>50,"Original resource item catalog loaded: "+prefabs.Length);Check(GameInfo.AllCreatureCount>10,"Original creature catalog loaded: "+GameInfo.AllCreatureCount);
 p.Vitals.Heal(100);p.Vitals.RestoreFullness(100);MainMenuManager.InstantCrash();PauseManager.TogglePause(false);RecoveryGiftPanel.Instance.SetOpen(false);yield return new WaitForSecondsRealtime(2);File.WriteAllText(Path.Combine(folder,"input-context.txt"),"blocked="+p.BlockInputs+" grounded="+p.Movement.Grounded+" boatDriving="+SelfDrivingBoat.IsDriving+" menu="+MainMenuManager.IsInMenu+" paused="+PauseManager.IsPaused+" pos="+p.Transform.position+"\n");
 InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;GameInfo.Input.ActivateInput();GameInfo.Input.actions.Enable();var kb=InputSystem.AddDevice<Keyboard>("RecoveryVerificationKeyboard");var mouse=InputSystem.AddDevice<Mouse>("RecoveryVerificationMouse");GameInfo.Input.SwitchCurrentControlScheme("Keyboard",kb,mouse);PlayerCamera.ToggleMouse(false);yield return null;InputSystem.QueueStateEvent(kb,new KeyboardState(Key.F8));yield return null;yield return null;Check(RecoveryGiftPanel.IsOpen,"F8 opens gift panel");InputSystem.QueueStateEvent(kb,new KeyboardState());yield return null;InputSystem.QueueStateEvent(kb,new KeyboardState(Key.F8));yield return null;yield return null;Check(!RecoveryGiftPanel.IsOpen,"F8 closes gift panel and restores player input");InputSystem.QueueStateEvent(kb,new KeyboardState());yield return null;File.AppendAllText(Path.Combine(folder,"input-context.txt"),"focus="+Application.isFocused+" map="+GameInfo.Input.currentActionMap+" moveEnabled="+GameInfo.Input.actions["PlayerMove"].enabled+" devices="+kb.enabled+","+mouse.enabled+"\n");var start=p.Transform.position;InputSystem.QueueStateEvent(kb,new KeyboardState(Key.S));yield return new WaitForSecondsRealtime(.8f);InputSystem.QueueStateEvent(kb,new KeyboardState());yield return null;float moved=Vector3.ProjectOnPlane(p.Transform.position-start,Vector3.up).magnitude;Check(moved>.2f,"Original InputSystem movement distance="+moved.ToString("F3"));var before=p.CamObject.rotation;InputSystem.QueueDeltaStateEvent(mouse.delta,new Vector2(100,0));yield return new WaitForSecondsRealtime(.2f);float turned=Quaternion.Angle(before,p.CamObject.rotation);Check(turned>.1f,"Original mouse look angle="+turned.ToString("F3"));float y=p.Transform.position.y,maxY=y;InputSystem.QueueStateEvent(kb,new KeyboardState(Key.Space));yield return new WaitForSecondsRealtime(.1f);InputSystem.QueueStateEvent(kb,new KeyboardState());float jumpEnd=Time.realtimeSinceStartup+.8f;while(Time.realtimeSinceStartup<jumpEnd){maxY=Mathf.Max(maxY,p.Transform.position.y);yield return null;}Check(maxY-y>.2f,"Original jump rise="+(maxY-y).ToString("F3"));InputSystem.RemoveDevice(kb);InputSystem.RemoveDevice(mouse);yield return Capture("original-player-view");
 var rodPrefab=prefabs.FirstOrDefault(x=>x is FishingRod);var weaponPrefab=prefabs.FirstOrDefault(x=>x is Weapon);var fishPrefab=prefabs.FirstOrDefault(x=>x is Creature c&&c.BossType==BossType.None);Check(rodPrefab&&weaponPrefab&&fishPrefab,"Original rod, weapon and fish fixtures available");
 foreach(byte id in new byte[]{0,1,2,3,4,6,7,8,9,10}){p=Player.LocalPlayer;if(!p||p.Dying.IsDead){Check(false,"Player unavailable for island traversal");break;}p.Vitals.Heal(100);p.Vitals.RestoreFullness(100);OnlineIslandManager.Instance._maxIslandUnlocked.Value=byte.MaxValue;OnlineIslandManager.ToggleTeleportPlayers(true,id>=6);OnlineIslandManager.Instance.SpawnIsland(id,id>=6,p,id>=6?(Vector2?)new Vector2(1500+id*500,1500):null);float timeout=Time.realtimeSinceStartup+25;yield return null;while((IslandManager.IsLoading||!Island.CurIsland||!SceneManager.GetSceneByBuildIndex(id+1).isLoaded)&&Time.realtimeSinceStartup<timeout)yield return null;Check(SceneManager.GetSceneByBuildIndex(id+1).isLoaded,"Original island load "+id+" => "+(Island.CurIsland?Island.CurIsland.gameObject.scene.name:"none"));yield return new WaitForSecondsRealtime(2);yield return Capture("island-"+id);}
 OnlineIslandManager.ToggleTeleportPlayers(true);OnlineIslandManager.Instance.SpawnIsland(0);yield return new WaitForSecondsRealtime(4);
 for(int i=0;i<GiftCatalog.All.Count;i++){var g=GiftCatalog.All[i];p=Player.LocalPlayer;if(!p){Check(false,"Player unavailable for "+g.id);break;}if(p.Dying.IsDead){Server.Instance.ResurrectPlayer(p,p.Dying.DeadPlayer);yield return new WaitForSecondsRealtime(1);p.Vitals.Heal(100);Check(!p.Dying.IsDead,"Fixture resurrected after destructive gifts");}p.Vitals._syncedHealth.Value=70;p.Vitals._syncedFullness.Value=70;p.Vitals._syncedFire.Value=0;p.Vitals._syncedPoison.Value=0;Server.Instance.TeleportPlayer(p,SpawnManager.MainSpawnPos,SpawnManager.MainSpawnRot);yield return new WaitForSecondsRealtime(.2f);
  if(g.id=="chaos/random_skin")Give(GameInfo.ItemWithSkinsforCommands.FirstOrDefault());else if(g.id.StartsWith("weapon/"))Give(weaponPrefab);else if(g.id.StartsWith("fishing/")||g.id=="bait/refill")Give(rodPrefab);else if(g.id=="chaos/cook_held_fish"||g.id=="chaos/random_skin"||g.id=="chaos/yeet_held_item")Give(fishPrefab);
  if(g.id=="boss/heal"){var bossPrefab=prefabs.FirstOrDefault(x=>x is Creature c&&c.BossType==BossType.Boss);if(bossPrefab){var b=ItemManager.Instance.SpawnNewItem(bossPrefab,p.Transform.position+Vector3.forward*35,Quaternion.identity);yield return new WaitForSecondsRealtime(.3f);b.Creature._hp.Value=Mathf.Max(1,b.Creature.MaxHp/2);}}
  if(g.id.Contains("boat")&&!BoatManager.Boat){var sp=UnityEngine.Object.FindObjectsByType<SpawnManager>(FindObjectsSortMode.None).FirstOrDefault();var bp=sp?Field(sp,"_boatPrefab") as Boat:null;if(bp){SaveManager.CurServerSave.UnlockedBoat=true;BoatManager.Instance.TrySpawnBoat(bp,SpawnManager.GetBoatSpawnPos(p.Transform.position),Quaternion.identity);yield return new WaitForSecondsRealtime(.3f);}}
  yield return new WaitForSecondsRealtime(.2f);string payload="{\"durationSeconds\":1,\"amount\":20,\"count\":1,\"birdCount\":1,\"uses\":1,\"fish\":\"random\",\"item\":\"random\",\"fuseSeconds\":1}";yield return Event(g.id,payload);var snapshot=JObject.Parse(state);string error=(string)snapshot["lastError"]??"";bool applied=RecoveryGiftPanel.Instance.LastResponse.Contains("\"ok\":true")&&(bool?)snapshot["ready"]==true&&(string)snapshot["lastEvent"]==g.id&&string.IsNullOrEmpty(error);Check(applied,"Original plugin event "+g.id+(error==""?"":" => "+error));if(g.id=="money/add")Check(snapshot["money"]!=null&&(int)snapshot["money"]>=20,"Original money gift changes wallet");if(g.id=="player/heal")Check(p.Vitals.Health>70,"Original heal changes vitals");if(g.id=="weapon/empty_mag")Check(p.Holding.HeldItem&&p.Holding.HeldItem.Weapon.Ammo==0,"Original empty-mag changes held weapon");if(new[]{"visual/sunset","visual/deep_fog","chaos/spawn_giant_fish","chaos/spawn_boss"}.Contains(g.id))yield return Capture(g.id.Replace('/','-'));
 }
 if(p.Dying.IsDead){Server.Instance.ResurrectPlayer(p,p.Dying.DeadPlayer);yield return new WaitForSecondsRealtime(1);}yield return new WaitForSecondsRealtime(3);yield return ReadState();Check(Mathf.Abs(Time.timeScale-1)<.01f,"Original time scale restores after timed gifts");
 OnlineIslandManager.ToggleTeleportPlayers(true);OnlineIslandManager.Instance.SpawnIsland(0);yield return new WaitForSecondsRealtime(3);RecoveryGiftPanel.Instance.SetOpen(true);yield return Capture("final-recovery-panel");File.WriteAllLines(Path.Combine(folder,"verification-results.txt"),new[]{"UTC "+DateTime.UtcNow.ToString("O"),"Checks="+lines.Count+" Failed="+failed}.Concat(lines));Debug.Log("[Recovery] VERIFY_COMPLETE failed="+failed);}
}
